-- ================================================================
--  STARTUP FUNDING & BANKRUPTCY — DATA ONLY
--  Tables: startups, investors, funding, bankruptcy
--  Startups : 10,500 | Investors : 500
--  Funding  : 33,615 | Bankruptcy: 1,625
-- ================================================================
-- drop database startup;
create database startup;
use startup;
DROP TABLE IF EXISTS bankruptcy;
DROP TABLE IF EXISTS funding;
DROP TABLE IF EXISTS investors;
DROP TABLE IF EXISTS startups;

CREATE TABLE startups (
    startup_id    INT PRIMARY KEY,
    startup_name  VARCHAR(100),
    industry      VARCHAR(50),
    country       VARCHAR(50),
    region        VARCHAR(50),
    city          VARCHAR(50),
    founded_year  INT,
    status        VARCHAR(20)
);

CREATE TABLE investors (
    investor_id   INT PRIMARY KEY,
    investor_name VARCHAR(100),
    investor_type VARCHAR(50),
    country       VARCHAR(50)
);

CREATE TABLE funding (
    funding_id    INT PRIMARY KEY,
    startup_id    INT,
    funding_date  DATE,
    funding_round VARCHAR(30),
    amount_usd    DECIMAL(15,2),
    investor_id   INT,
    FOREIGN KEY (startup_id)  REFERENCES startups(startup_id),
    FOREIGN KEY (investor_id) REFERENCES investors(investor_id)
);

CREATE TABLE bankruptcy (
    bankruptcy_id        INT PRIMARY KEY,
    startup_id           INT,
    bankruptcy_date      DATE,
    reason               VARCHAR(200),
    total_funding_raised DECIMAL(15,2),
    FOREIGN KEY (startup_id) REFERENCES startups(startup_id)
);
-- Add closure_reason column to startups table
CREATE TABLE closure_reason (
    id INT PRIMARY KEY,
    startup_id INT,
    closure_reason VARCHAR(200),
	FOREIGN KEY (startup_id) REFERENCES startups(startup_id)
);
-- Insert closure_reason values
-- Format: (id, startup_id, closure_reason)

	






























































































  
  


  
-- --- ---- ---- -- -- -- -- -- - - - - - - - - - - -  - -- - - -
use startup;
select * from startups;
select * from investors;
select * from bankruptcy;
select * from funding;
select * from closure_reason;

# Display total  startup --Kpis 

select count(*) As Total_startups from startups;

# Display Total Finding 

select concat(round(sum(amount_usd)/1000000000000,2),'T') as Total_funding from funding;

# display total Active startup -- Kpis 

select count(*) as Total_Active_startups
from startups  
	where  status in ('active','ipo','Acquired');

# Display  Startup Survival Rate (%) -- kpis 

select  concat(
	round(sum(case
	when status in ('active','ipo','Acquired') 
    then 1 else 0 end)*100/count(*),2),'%')
    as Startup_Survival_Rate
from startups;

# Diplay starups is Inactive or Bankrupt Rate(%)-- kpi

select concat(
	round(
    sum(
    case when status in('Inactive','Bankrupt') then 1 else 0 end)/count(*),2),'%'
    )as Closure_Raten 
from startups;
# total Finding By industry
select s.industry , concat(
	round(sum(f.amount_usd)/10000000000,2),'B') as total_funding 
from startups  s join funding f 
	on s.startup_id=f.startup_id
    group by s.industry
	order by total_funding desc;

# Display all active startups

select 
	S.startup_id,
    s.industry,
    s.country,
    s.status,
    c.closure_reason
from startups  s  
	join closure_reason  c  
	on s.startup_id = c.startup_id 
	where s.status in ('Active','ipo','Acquired');

# Find Top 5 Funded Startups in Each Industry

with startup_funding as (
 select 
	s.startup_id,
    s.startup_name,
    s.industry,
    sum(f.amount_usd) as total_funding 
from startups s 
	join funding f on s.startup_id = f.startup_id 
    group by s.startup_id,s.startup_name,s.industry )
    
select * from
		(select *, dense_rank() 
			over(partition by industry order by total_funding) as ranks 
		from startup_funding)x 
			where ranks<=5;

# Find Investors Who Invested in Bankrupt Startups

select 
	distinct  
    i.investor_name,
    s.startup_name,
    b.reason 
from investors as i 
		join funding as f on i.investor_id=f.investor_id 
        join startups as s on f.startup_id=s.startup_id 
        join bankruptcy as b on s.startup_id=b.startup_id;
 

# Runging Total Funding 

select startup_id,
	funding_date,
	amount_usd,
	sum(amount_usd) over(partition by startup_id order by funding_date) as  running_funding 
 from funding;
 
 # Funding Growth Between Rounds
 
 with funding_growth as ( select startup_id,
	funding_date,
	funding_round,
	amount_usd,
 lag(amount_usd) over(partition by startup_id  order by year(funding_date)) as previous_amount 
 from funding
 )
 select startup_id,
	funding_date,
	funding_round,
	amount_usd,
    previous_amount,
    concat(
	round(
    (( amount_usd-previous_amount)/previous_amount)*100,2),'%')as growth_rate 
from funding_growth 
where previous_amount is not null;

CALL StartupReport('StartupReport');